"""Positive control for joint_census2 (E82): targets generated by the model itself at a random S*, L* on a line must be
recovered by the same fitter (same starts, solver, floor). Reports chi2 at the planted world and the fitter's best."""
import math, pathlib, sys
import numpy as np
src = pathlib.Path(__file__).with_name("joint_census2.py").read_text(encoding="utf-8")
head = src.split("out = []")[0]
sys.argv = ["x", "11", sys.argv[1] if len(sys.argv) > 1 else "48"]
NS = {"__file__": str(pathlib.Path(__file__).with_name("joint_census2.py")), "__name__": "jc2"}
exec(compile(head, "jc2", "exec"), NS)
svs, unpack, least_squares, DATA, NSTART = NS["svs"], NS["unpack"], NS["least_squares"], NS["DATA"], NS["NSTART"]
rng = np.random.default_rng(99)
for trial, ln in enumerate(sorted(DATA)[::6]):
    # a planted world: S* nearly null (so the hierarchy is the model's own), L* moderate
    u, v = rng.normal(size=2) + 1j*rng.normal(size=2), rng.normal(size=2) + 1j*rng.normal(size=2)
    Sst = np.outer(u, v) + 0.03*(rng.normal(size=(2, 2)) + 1j*rng.normal(size=(2, 2))); Lst = 10**rng.uniform(0.7, 2.0)
    sv = svs(Sst, ln, Lst)
    tg = [("up", 1), ("up", 2), ("down", 1), ("down", 2), ("lep", 1)]
    mus = [math.log(sv[s][k]/sv[s][0]) for s, k in tg]
    def resid(p):
        S, L = unpack(p)
        if 2*np.pi*L + min(min(NS["PARTS"][ln][s][0]) for s in ("up", "down", "lep")) <= 0: return np.full(5, 1e3)
        q = svs(S, ln, L)
        return np.array([(math.log(max(q[s][k]/q[s][0], 1e-300)) - mu)/0.05 for (s, k), mu in zip(tg, mus)])
    best = None
    for st in range(NSTART):
        p0 = np.concatenate([rng.normal(size=8), [math.log(10**rng.uniform(0.3, 3.5))]])
        r = least_squares(resid, p0, method="trf", max_nfev=400, xtol=1e-12, ftol=1e-12, gtol=1e-12)
        if best is None or r.cost < best.cost: best = r
    print(f"control {trial} line {ln[0]:.3f},{ln[1]:.3f}: planted ratios {np.round(np.exp(mus), 5).tolist()} L* {Lst:.1f}; "
          f"fitter best chi2 {2*best.cost:.3g}", flush=True)
